package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/notification-service/internal/delivery"
	"github.com/luwa07832/notification-service/internal/store"
)

const codeInvalidSearch = "INVALID_DELIVERY_SEARCH"

// searchDeliveryRecords handles GET /api/v1/delivery-records/search. The
// channel and half-open time range keep the same meaning as the basic list
// entry; the remaining conditions narrow the search for failure tracking.
func searchDeliveryRecords(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		input := delivery.SearchInput{
			Channel: c.Query("channel"),
			Start:   c.Query("start"),
			End:     c.Query("end"),
		}
		if value, ok := c.GetQuery("template_id"); ok {
			input.TemplateID = &value
		}
		if value, ok := c.GetQuery("status"); ok {
			input.Status = &value
		}
		if value, ok := c.GetQuery("retry_min"); ok {
			input.RetryMin = &value
		}
		if value, ok := c.GetQuery("retry_max"); ok {
			input.RetryMax = &value
		}
		if value, ok := c.GetQuery("failure_reason_contains"); ok {
			input.FailureReasonContain = &value
		}
		if value, ok := c.GetQuery("page"); ok {
			input.Page = &value
		}
		if value, ok := c.GetQuery("page_size"); ok {
			input.PageSize = &value
		}

		query, err := delivery.NewSearch(input)
		if err != nil {
			respondError(c, http.StatusBadRequest, codeInvalidSearch, "delivery search parameters are not valid")
			return
		}

		result, err := st.SearchDeliveryRecords(c.Request.Context(), query)
		if err != nil {
			respondError(c, http.StatusServiceUnavailable, codeStorageDown, "delivery record storage is not available")
			return
		}
		c.JSON(http.StatusOK, gin.H{
			"records": result.Records,
			"pagination": gin.H{
				"page":      query.Page,
				"page_size": query.PageSize,
				"total":     result.Total,
			},
		})
	}
}
package delivery

import (
	"errors"
	"strconv"
	"strings"
	"time"
)

// ErrInvalidSearch marks a failed advanced-search parameter validation. The
// HTTP layer maps it to the published INVALID_DELIVERY_SEARCH error code.
var ErrInvalidSearch = errors.New("invalid delivery search")

const (
	// DefaultSearchPageSize is used when page_size is omitted.
	DefaultSearchPageSize = 50
	// MaxSearchPageSize caps how many records one page may return.
	MaxSearchPageSize = 200
)

// SearchInput carries the raw search parameters as received on the query
// string. Pointer fields distinguish an omitted parameter from an empty one:
// a present but empty value is invalid, while nil means the filter is unused.
type SearchInput struct {
	Channel              string
	Start                string
	End                  string
	TemplateID           *string
	Status               *string
	RetryMin             *string
	RetryMax             *string
	FailureReasonContain *string
	Page                 *string
	PageSize             *string
}

// SearchQuery is the validated advanced search. It shares the channel and
// half-open [Start, End) semantics with the basic list query and adds optional
// failure-tracking filters plus one-based pagination.
type SearchQuery struct {
	Channel              string
	Start                time.Time
	End                  time.Time
	TemplateID           *string
	Status               *string
	RetryMin             *int
	RetryMax             *int
	FailureReasonContain *string
	Page                 int
	PageSize             int
}

// NewSearch validates every search parameter. All supplied conditions must
// hold for a record to match, so even one malformed value rejects the request.
func NewSearch(in SearchInput) (SearchQuery, error) {
	if !IsAllowedChannel(strings.TrimSpace(in.Channel)) || in.Channel != strings.TrimSpace(in.Channel) {
		return SearchQuery{}, ErrInvalidSearch
	}
	start, err := time.Parse(time.RFC3339, in.Start)
	if err != nil {
		return SearchQuery{}, ErrInvalidSearch
	}
	end, err := time.Parse(time.RFC3339, in.End)
	if err != nil {
		return SearchQuery{}, ErrInvalidSearch
	}
	if !start.Before(end) {
		return SearchQuery{}, ErrInvalidSearch
	}

	query := SearchQuery{
		Channel:  in.Channel,
		Start:    start.UTC(),
		End:      end.UTC(),
		Page:     1,
		PageSize: DefaultSearchPageSize,
	}

	if in.TemplateID != nil {
		templateID := strings.TrimSpace(*in.TemplateID)
		if templateID == "" {
			return SearchQuery{}, ErrInvalidSearch
		}
		query.TemplateID = &templateID
	}
	if in.Status != nil {
		if !IsAllowedStatus(*in.Status) {
			return SearchQuery{}, ErrInvalidSearch
		}
		query.Status = in.Status
	}
	if in.RetryMin != nil {
		retryMin, ok := parseNonNegativeInt(*in.RetryMin)
		if !ok {
			return SearchQuery{}, ErrInvalidSearch
		}
		query.RetryMin = &retryMin
	}
	if in.RetryMax != nil {
		retryMax, ok := parseNonNegativeInt(*in.RetryMax)
		if !ok {
			return SearchQuery{}, ErrInvalidSearch
		}
		query.RetryMax = &retryMax
	}
	if query.RetryMin != nil && query.RetryMax != nil && *query.RetryMin > *query.RetryMax {
		return SearchQuery{}, ErrInvalidSearch
	}
	if in.FailureReasonContain != nil {
		if *in.FailureReasonContain == "" {
			return SearchQuery{}, ErrInvalidSearch
		}
		query.FailureReasonContain = in.FailureReasonContain
	}
	if in.Page != nil {
		page, ok := parsePositiveInt(*in.Page)
		if !ok {
			return SearchQuery{}, ErrInvalidSearch
		}
		query.Page = page
	}
	if in.PageSize != nil {
		pageSize, ok := parsePositiveInt(*in.PageSize)
		if !ok || pageSize > MaxSearchPageSize {
			return SearchQuery{}, ErrInvalidSearch
		}
		query.PageSize = pageSize
	}
	return query, nil
}

// parseNonNegativeInt accepts decimal non-negative integers only. Signs,
// whitespace, fractions and empty input are rejected.
func parseNonNegativeInt(raw string) (int, bool) {
	if raw == "" {
		return 0, false
	}
	for _, r := range raw {
		if r < '0' || r > '9' {
			return 0, false
		}
	}
	value, err := strconv.Atoi(raw)
	if err != nil || value < 0 {
		return 0, false
	}
	return value, true
}

// parsePositiveInt shares the strict integer parsing and additionally requires
// a value of at least one.
func parsePositiveInt(raw string) (int, bool) {
	value, ok := parseNonNegativeInt(raw)
	if !ok || value < 1 {
		return 0, false
	}
	return value, true
}
package store

import (
	"context"
	"fmt"
	"strings"

	"github.com/luwa07832/notification-service/internal/delivery"
)

// SearchResult is one page of an advanced search together with the exact
// total number of records matching every supplied condition.
type SearchResult struct {
	Records []delivery.Record
	Total   int
}

// SearchDeliveryRecords returns one page of registered records matching the
// validated search. Matching only reads existing rows: registration, retry
// handling and stored failure reasons stay untouched.
func (s *Store) SearchDeliveryRecords(ctx context.Context, search delivery.SearchQuery) (SearchResult, error) {
	clauses := []string{
		"channel = ?",
		"occurred_at >= ?",
		"occurred_at < ?",
	}
	args := []any{
		search.Channel,
		search.Start.UTC().Format(storedTimeFormat),
		search.End.UTC().Format(storedTimeFormat),
	}
	if search.TemplateID != nil {
		clauses = append(clauses, "template_id = ?")
		args = append(args, *search.TemplateID)
	}
	if search.Status != nil {
		clauses = append(clauses, "status = ?")
		args = append(args, *search.Status)
	}
	if search.RetryMin != nil {
		clauses = append(clauses, "retry_count >= ?")
		args = append(args, *search.RetryMin)
	}
	if search.RetryMax != nil {
		clauses = append(clauses, "retry_count <= ?")
		args = append(args, *search.RetryMax)
	}
	if search.FailureReasonContain != nil {
		clauses = append(clauses, "instr(failure_reason, ?) > 0")
		args = append(args, *search.FailureReasonContain)
	}
	filter := strings.Join(clauses, " AND ")

	var total int
	if err := s.db.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM delivery_records WHERE `+filter,
		args...,
	).Scan(&total); err != nil {
		return SearchResult{}, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
	}

	limit := search.PageSize
	offset := (search.Page - 1) * search.PageSize
	pageArgs := make([]any, 0, len(args)+2)
	pageArgs = append(pageArgs, args...)
	pageArgs = append(pageArgs, limit, offset)

	rows, err := s.db.QueryContext(ctx,
		`SELECT id, template_id, channel, occurred_at, status, retry_count, failure_reason, notification_id
		   FROM delivery_records
		  WHERE `+filter+`
		  ORDER BY occurred_at ASC, id ASC
		  LIMIT ? OFFSET ?`,
		pageArgs...,
	)
	if err != nil {
		return SearchResult{}, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
	}
	defer rows.Close()

	records := []delivery.Record{}
	for rows.Next() {
		record, err := scanDeliveryRecord(rows)
		if err != nil {
			return SearchResult{}, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
		}
		records = append(records, record)
	}
	if err := rows.Err(); err != nil {
		return SearchResult{}, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
	}
	return SearchResult{Records: records, Total: total}, nil
}

